return [
    'writes epub3 package bytes with opf nav spine and metadata' => static function (TestRunner $t): void {
        $document = new AstNode('document', [
            'meta' => [
                'identifier' => 'urn:isbn:9780000000000',
                'title' => 'EPUB Export Demo',
                'author' => 'Port Libs',
                'lang' => 'en-US',
                'description' => 'A bounded EPUB3 writer smoke.',
            ],
        ], [
            new AstNode('heading', ['level' => 1, 'text' => 'Export Demo'], [
                new AstNode('text', ['text' => 'Export Demo']),
            ]),
            new AstNode('paragraph', [], [
                new AstNode('text', ['text' => 'A generated ']),
                new AstNode('strong', [], [
                    new AstNode('text', ['text' => 'chapter']),
                ]),
                new AstNode('text', ['text' => ' with a ']),
                new AstNode('link', ['url' => 'https://example.test/'], [
                    new AstNode('text', ['text' => 'link']),
                ]),
                new AstNode('text', ['text' => '.']),
            ]),
        ]);

        $epub = PandocConverter::write($document, 'epub3', [
            'modified' => '2026-06-21T00:00:00Z',
        ]);
        $path = tempnam(sys_get_temp_dir(), 'pandoc-epub-writer-');
        if ($path === false) {
            throw new RuntimeException('Unable to create temporary EPUB path');
        }
        file_put_contents($path, $epub);

        $zip = new ZipArchive();
        try {
            if ($zip->open($path) !== true) {
                throw new RuntimeException('Unable to open generated EPUB package');
            }

            $t->same('application/epub+zip', $zip->getFromName('mimetype'));
            $container = $zip->getFromName('META-INF/container.xml');
            $package = $zip->getFromName('OEBPS/package.opf');
            $chapter = $zip->getFromName('OEBPS/text/chapter.xhtml');
            $nav = $zip->getFromName('OEBPS/nav.xhtml');
            if (!is_string($container) || !is_string($package) || !is_string($chapter) || !is_string($nav)) {
                throw new RuntimeException('Generated EPUB package is missing required files');
            }

            $t->contains('full-path="OEBPS/package.opf"', $container);
            $t->contains('<dc:identifier id="book-id">urn:isbn:9780000000000</dc:identifier>', $package);
            $t->contains('<dc:title>EPUB Export Demo</dc:title>', $package);
            $t->contains('<dc:creator>Port Libs</dc:creator>', $package);
            $t->contains('<dc:language>en-US</dc:language>', $package);
            $t->contains('<meta property="dcterms:modified">2026-06-21T00:00:00Z</meta>', $package);
            $t->same(1, substr_count($package, '<metadata>'));
            $t->same(1, substr_count($package, '</metadata>'));
            $t->contains('<item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>', $package);
            $t->contains('<itemref idref="chapter-1"/>', $package);
            $t->contains('<h1 id="export-demo">Export Demo</h1>', $chapter);
            $t->contains('<strong>chapter</strong>', $chapter);
            $t->contains('<a href="https://example.test/">link</a>', $chapter);
            $t->contains('<a href="text/chapter.xhtml#export-demo">Export Demo</a>', $nav);
        } finally {
            $zip->close();
            @unlink($path);
        }

        $roundTrip = PandocConverter::read($epub, 'epub');
        $meta = $roundTrip->attr('meta');
        $t->same('EPUB Export Demo', $meta['title']);
        $t->same('Port Libs', $meta['author']);
        $t->same('en-US', $meta['lang']);
        $t->same('heading', $roundTrip->children[0]->type);
        $t->same('Export Demo', $roundTrip->children[0]->attr('text'));
    },
    'writes bounded epub2 package bytes with opf2 ncx spine and metadata' => static function (TestRunner $t): void {
        $document = new AstNode('document', [
            'meta' => [
                'identifier' => 'urn:isbn:9780000000002',
                'title' => 'EPUB2 Export Demo',
                'author' => 'Port Libs',
                'lang' => 'en-US',
                'description' => 'A bounded EPUB2 writer smoke.',
                'epubGuideReferences' => [
                    ['type' => 'text', 'title' => 'Start', 'href' => 'OEBPS/text/chapter.xhtml#epub2-export-demo'],
                ],
            ],
        ], [
            new AstNode('heading', ['level' => 1, 'text' => 'EPUB2 Export Demo'], [
                new AstNode('text', ['text' => 'EPUB2 Export Demo']),
            ]),
            new AstNode('paragraph', [], [
                new AstNode('text', ['text' => 'A generated EPUB2 chapter.']),
            ]),
        ]);

        $epub = PandocConverter::write($document, 'epub2', [
            'modified' => '2026-06-23T00:00:00Z',
            'coverImage' => 'OEBPS/images/cover.png',
            'resources' => [
                'OEBPS/images/cover.png' => 'png-cover-bytes',
            ],
        ]);
        $path = tempnam(sys_get_temp_dir(), 'pandoc-epub2-writer-');
        if ($path === false) {
            throw new RuntimeException('Unable to create temporary EPUB2 path');
        }
        file_put_contents($path, $epub);

        $zip = new ZipArchive();
        try {
            if ($zip->open($path) !== true) {
                throw new RuntimeException('Unable to open generated EPUB2 package');
            }

            $t->same('application/epub+zip', $zip->getFromName('mimetype'));
            $container = $zip->getFromName('META-INF/container.xml');
            $package = $zip->getFromName('OEBPS/package.opf');
            $chapter = $zip->getFromName('OEBPS/text/chapter.xhtml');
            $ncx = $zip->getFromName('OEBPS/toc.ncx');
            if (!is_string($container) || !is_string($package) || !is_string($chapter) || !is_string($ncx)) {
                throw new RuntimeException('Generated EPUB2 package is missing required files');
            }

            $t->contains('full-path="OEBPS/package.opf"', $container);
            $t->same('png-cover-bytes', $zip->getFromName('OEBPS/images/cover.png'));
            $t->same(false, $zip->locateName('OEBPS/nav.xhtml'));
            $t->contains('<package xmlns="http://www.idpf.org/2007/opf" xmlns:dc="http://purl.org/dc/elements/1.1/" version="2.0" unique-identifier="book-id">', $package);
            $t->contains('<dc:identifier id="book-id">urn:isbn:9780000000002</dc:identifier>', $package);
            $t->contains('<dc:title>EPUB2 Export Demo</dc:title>', $package);
            $t->contains('<dc:creator>Port Libs</dc:creator>', $package);
            $t->contains('<dc:language>en-US</dc:language>', $package);
            $t->contains('<meta name="cover" content="cover"/>', $package);
            $t->contains('<item id="toc" href="toc.ncx" media-type="application/x-dtbncx+xml"/>', $package);
            $t->contains('<item id="chapter-1" href="text/chapter.xhtml" media-type="application/xhtml+xml"/>', $package);
            $t->contains('<item id="cover" href="images/cover.png" media-type="image/png"/>', $package);
            $t->contains('<spine toc="toc">', $package);
            $t->contains('<itemref idref="chapter-1"/>', $package);
            $t->contains('<reference type="cover" title="Cover" href="images/cover.png"/>', $package);
            $t->contains('<reference type="text" title="Start" href="text/chapter.xhtml#epub2-export-demo"/>', $package);
            $t->true(!str_contains($package, 'properties="nav"'), 'EPUB2 package should not include an EPUB3 nav manifest item.');
            $t->true(!str_contains($package, 'properties="cover-image"'), 'EPUB2 cover metadata should use meta name cover instead of the EPUB3 cover-image property.');
            $t->true(!str_contains($package, 'nav.xhtml'), 'EPUB2 package should not reference nav.xhtml.');
            $t->true(!str_contains($package, 'dcterms:modified'), 'EPUB2 package should not emit EPUB3 dcterms:modified metadata.');
            $t->true(!str_contains($package, 'prefix='), 'EPUB2 package should not emit EPUB3 package prefix attributes.');
            $t->contains('<h1 id="epub2-export-demo">EPUB2 Export Demo</h1>', $chapter);
            $t->contains('<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1">', $ncx);
            $t->contains('<content src="text/chapter.xhtml#epub2-export-demo"/>', $ncx);
        } finally {
            $zip->close();
            @unlink($path);
        }

        $roundTrip = PandocConverter::read($epub, 'epub');
        $meta = $roundTrip->attr('meta');
        $diagnosticsJson = json_encode($meta['epubDiagnostics'] ?? [], JSON_THROW_ON_ERROR);
        $t->same('2.0', $meta['epubPackageVersion'] ?? null);
        $t->same('EPUB2 Export Demo', $meta['title']);
        $t->same('Port Libs', $meta['author']);
        $t->same('en-US', $meta['lang']);
        $t->same('cover', $meta['epubCoverItemId'] ?? null);
        $t->same('OEBPS/images/cover.png', $meta['epubCoverImage'] ?? null);
        $t->same(['OEBPS/images/cover.png'], $meta['epubImageResources'] ?? null);
        $t->same([
            ['type' => 'cover', 'title' => 'Cover', 'href' => 'OEBPS/images/cover.png'],
            ['type' => 'text', 'title' => 'Start', 'href' => 'OEBPS/text/chapter.xhtml#epub2-export-demo'],
        ], $meta['epubGuideReferences'] ?? null);
        $t->true(!str_contains($diagnosticsJson, 'unsupported-package-version'), 'Generated OPF 2.0 package should be accepted by the reader.');
        $t->true(!str_contains($diagnosticsJson, 'invalid-package-opf2-meta'), 'Generated OPF 2.0 cover metadata should not be treated as invalid OPF2 metadata.');
        $t->same('heading', $roundTrip->children[0]->type);
        $t->same('EPUB2 Export Demo', $roundTrip->children[0]->attr('text'));
    },
    'writes bounded epub2 guide references without invalid target self diagnostics' => static function (TestRunner $t): void {
        $document = new AstNode('document', [
            'meta' => [
                'identifier' => 'urn:uuid:epub2-guide-reference-sanitation',
                'title' => 'EPUB2 Guide Reference Sanitation',
                'lang' => 'en',
                'epubGuideReferences' => [
                    ['type' => 'text', 'title' => 'Start', 'href' => 'OEBPS/text/chapter.xhtml#epub2-guide-start'],
                    ['type' => 'loi', 'title' => 'Remote Figures', 'href' => 'https://cdn.example.test/epub2-figures.xhtml'],
                    ['type' => 'glossary', 'title' => '', 'href' => 'OEBPS/text/chapter.xhtml#epub2-guide-start'],
                    ['type' => 'appendix', 'title' => 'Backmatter', 'href' => 'OEBPS/text/backmatter.xhtml#epub2-guide-backmatter'],
                    ['type' => 'appendix', 'title' => 'Backmatter Duplicate', 'href' => 'OEBPS/text/backmatter.xhtml#epub2-guide-backmatter'],
                    ['type' => '', 'title' => 'Missing Type', 'href' => 'OEBPS/text/chapter.xhtml#epub2-guide-start'],
                    ['type' => 'bad type', 'title' => 'Invalid Type', 'href' => 'OEBPS/text/chapter.xhtml#epub2-guide-start'],
                    ['type' => 'text', 'title' => 'Missing Href', 'href' => ''],
                    ['type' => 'loi', 'title' => 'Missing Resource', 'href' => 'OEBPS/missing.xhtml'],
                    ['type' => 'index', 'title' => 'Missing Fragment', 'href' => 'OEBPS/text/chapter.xhtml#missing-fragment'],
                    ['type' => 'text', 'title' => 'Malformed Resource', 'href' => 'OEBPS/text/broken-guide.xhtml#start'],
                    ['type' => 'text', 'title' => 'Image Fragment', 'href' => 'OEBPS/images/diagram.png#diagram'],
                    ['type' => 'text', 'title' => 'Empty Fragment', 'href' => 'OEBPS/text/chapter.xhtml#'],
                    ['type' => 'text', 'title' => 'Whitespace Fragment', 'href' => 'OEBPS/text/chapter.xhtml#bad%20target'],
                    ['type' => 'text', 'title' => 'Query Only', 'href' => '?print=1'],
                    ['type' => 'cover', 'title' => 'Fragment Only', 'href' => '#cover'],
                    ['type' => 'cover', 'title' => 'Data Cover', 'href' => 'data:image/svg+xml;base64,PHN2Zy8+'],
                    ['type' => 'text', 'title' => 'File Guide', 'href' => 'file:///tmp/chapter.xhtml'],
                    ['type' => 'text', 'title' => 'Absolute Path', 'href' => '/chapter.xhtml'],
                    ['type' => 'text', 'title' => 'Protocol Relative', 'href' => '//cdn.example.test/chapter.xhtml'],
                    ['type' => 'text', 'title' => 'Backslash Path', 'href' => 'chapters\\one.xhtml'],
                    ['type' => 'text', 'title' => 'Encoded Dot Segment', 'href' => 'chapters/%2e%2e/chapter.xhtml'],
                ],
            ],
        ], [
            new AstNode('heading', ['level' => 1, 'text' => 'EPUB2 Guide Reference Sanitation', 'id' => 'epub2-guide-start'], [
                new AstNode('text', ['text' => 'EPUB2 Guide Reference Sanitation']),
            ]),
            new AstNode('paragraph', [], [
                new AstNode('text', ['text' => 'EPUB2 guide reference sanitation body.']),
            ]),
        ]);

        $epub = PandocConverter::write($document, 'epub2', [
            'modified' => '2026-06-23T00:00:00Z',
            'resources' => [
                'OEBPS/text/backmatter.xhtml' => '<html xmlns="http://www.w3.org/1999/xhtml"><body><section id="epub2-guide-backmatter"><h1>Backmatter</h1></section></body></html>',
                'OEBPS/text/broken-guide.xhtml' => '<html xmlns="http://www.w3.org/1999/xhtml"><body><p id="start">Broken guide target</p>',
                'OEBPS/images/diagram.png' => 'not-a-real-png',
            ],
        ]);
        $path = tempnam(sys_get_temp_dir(), 'pandoc-epub2-guide-reference-sanitized-');
        if ($path === false) {
            throw new RuntimeException('Unable to create temporary EPUB2 guide-reference sanitation path');
        }
        file_put_contents($path, $epub);

        $zip = new ZipArchive();
        try {
            if ($zip->open($path) !== true) {
                throw new RuntimeException('Unable to open generated EPUB2 guide-reference sanitation package');
            }
            $package = $zip->getFromName('OEBPS/package.opf');
            if (!is_string($package)) {
                throw new RuntimeException('Generated EPUB2 guide-reference sanitation package is missing package OPF');
            }

            $t->contains('<package xmlns="http://www.idpf.org/2007/opf" xmlns:dc="http://purl.org/dc/elements/1.1/" version="2.0" unique-identifier="book-id">', $package);
            $t->contains('<reference type="text" title="Start" href="text/chapter.xhtml#epub2-guide-start"/>', $package);
            $t->contains('<reference type="loi" title="Remote Figures" href="https://cdn.example.test/epub2-figures.xhtml"/>', $package);
            $t->contains('<reference type="glossary" title="Glossary" href="text/chapter.xhtml#epub2-guide-start"/>', $package);
            $t->contains('<reference type="appendix" title="Backmatter" href="text/backmatter.xhtml#epub2-guide-backmatter"/>', $package);
            foreach ([
                'Backmatter Duplicate',
                'Missing Type',
                'Invalid Type',
                'Missing Href',
                'Missing Resource',
                'Missing Fragment',
                'Malformed Resource',
                'Image Fragment',
                'Empty Fragment',
                'Whitespace Fragment',
                'Query Only',
                'Fragment Only',
                'Data Cover',
                'File Guide',
                'Absolute Path',
                'Protocol Relative',
                'Backslash Path',
                'Encoded Dot Segment',
            ] as $omittedGuideReference) {
                $t->true(!str_contains($package, $omittedGuideReference), "Invalid EPUB2 guide reference should not be emitted: {$omittedGuideReference}.");
            }
        } finally {
            $zip->close();
            @unlink($path);
        }

        $roundTrip = PandocConverter::read($epub, 'epub');
        $meta = $roundTrip->attr('meta');
        $diagnosticsJson = json_encode($meta['epubDiagnostics'] ?? [], JSON_THROW_ON_ERROR);
        $guideReferencesJson = json_encode($meta['epubGuideReferences'] ?? [], JSON_THROW_ON_ERROR);
        $t->same('2.0', $meta['epubPackageVersion'] ?? null);
        $t->same([
            ['type' => 'text', 'title' => 'Start', 'href' => 'OEBPS/text/chapter.xhtml#epub2-guide-start'],
            ['type' => 'loi', 'title' => 'Remote Figures', 'href' => 'https://cdn.example.test/epub2-figures.xhtml'],
            ['type' => 'glossary', 'title' => 'Glossary', 'href' => 'OEBPS/text/chapter.xhtml#epub2-guide-start'],
            ['type' => 'appendix', 'title' => 'Backmatter', 'href' => 'OEBPS/text/backmatter.xhtml#epub2-guide-backmatter'],
        ], $meta['epubGuideReferences'] ?? null);
        foreach ([
            'unsupported-package-version',
            'missing-package-modified',
            'missing-guide-reference-type',
            'invalid-guide-reference-type',
            'missing-guide-reference-title',
            'missing-guide-reference-href',
            'missing-guide-reference-resource',
            'missing-guide-reference-manifest-resource',
            'missing-guide-reference-fragment',
            'malformed-guide-reference-resource',
            'invalid-guide-reference-href-path',
            'invalid-guide-reference-href-fragment',
            'invalid-guide-reference-data-url',
            'invalid-guide-reference-file-url',
        ] as $diagnosticCode) {
            $t->true(!str_contains($diagnosticsJson, $diagnosticCode), "Generated EPUB2 guide references should not self-diagnose {$diagnosticCode}.");
        }
        foreach (['Backmatter Duplicate', 'Missing Resource', 'Missing Fragment', 'Malformed Resource', 'Image Fragment', 'Data Cover', 'File Guide'] as $omitted) {
            $t->true(!str_contains($guideReferencesJson, $omitted), "Invalid EPUB2 guide reference should not round-trip: {$omitted}.");
        }
    },
    'writes bounded epub2 ncx compatibility metadata without epub3 nav output' => static function (TestRunner $t): void {
        $document = new AstNode('document', [
