            $t->contains('<pageList>', $ncx);
            $t->contains('<navLabel xml:lang="de"><text>Seiten</text></navLabel>', $ncx);
            $t->contains('<pageTarget id="epub2-page-one-ncx" playOrder="12" type="normal" value="1">', $ncx);
            $t->contains('<navLabel xml:lang="fr"><text>1</text></navLabel>', $ncx);
            $t->contains('<pageTarget id="epub2-page-one-note-ncx" playOrder="15" type="special" value="1a">', $ncx);
            $t->contains('<navList id="epub2-figures" class="loi">', $ncx);
            $t->contains('<navLabel xml:lang="en"><text>Figures</text></navLabel>', $ncx);
            $t->contains('<navTarget id="epub2-figure-one-ncx" playOrder="18" class="figure">', $ncx);
            $t->contains('<content src="text/chapter.xhtml#epub2-figure-1"/>', $ncx);
        } finally {
            $zip->close();
            @unlink($path);
        }

        $roundTrip = PandocConverter::read($epub, 'epub');
