                new AstNode('text', ['text' => 'The first auxiliary target starts here.']),
            ]),
            new AstNode('heading', ['level' => 1, 'text' => 'Split Figure Two', 'id' => 'split-figure-two'], [
                new AstNode('text', ['text' => 'Split Figure Two']),
            ]),
            new AstNode('paragraph', [], [
                new AstNode('text', ['text' => 'The second auxiliary target is in the second split file.']),
            ]),
            new AstNode('heading', ['level' => 2, 'text' => 'Split Table Two', 'id' => 'split-table-two'], [
                new AstNode('text', ['text' => 'Split Table Two']),
            ]),
            new AstNode('paragraph', [], [
                new AstNode('text', ['text' => 'A lower-level auxiliary target remains in the second split file.']),
            ]),
        ]);

        $epub = PandocConverter::write($document, 'epub3', [
            'modified' => '2026-06-23T13:20:00Z',
            'splitLevel' => 1,
