        if ($path === false) {
            throw new RuntimeException('Unable to create temporary split auxiliary navigation EPUB path');
        }
        file_put_contents($path, $epub);

        $zip = new ZipArchive();
        try {
            if ($zip->open($path) !== true) {
                throw new RuntimeException('Unable to open generated split auxiliary navigation EPUB package');
            }
            $nav = $zip->getFromName('OEBPS/nav.xhtml');
            $chapterOne = $zip->getFromName('OEBPS/text/chapter.xhtml');
            $chapterTwo = $zip->getFromName('OEBPS/text/chapter-2.xhtml');
            if (!is_string($nav) || !is_string($chapterOne) || !is_string($chapterTwo)) {
                throw new RuntimeException('Generated split auxiliary navigation EPUB package is missing nav or split chapter files');
            }

            $t->contains('<h1 id="split-figure-one">Split Figure One</h1>', $chapterOne);
            $t->true(!str_contains($chapterOne, 'split-figure-two'), 'First split auxiliary nav chapter leaked the second heading.');
            $t->contains('<h1 id="split-figure-two">Split Figure Two</h1>', $chapterTwo);
            $t->contains('<h2 id="split-table-two">Split Table Two</h2>', $chapterTwo);
            $t->true(!str_contains($chapterTwo, 'split-figure-one'), 'Second split auxiliary nav chapter leaked the first heading.');
            $t->contains('<nav epub:type="loi" id="split-figures-nav" class="split-figures">', $nav);
            $t->contains('<h3 id="split-figures-heading" class="split-aux-heading">Split Figures</h3>', $nav);
            $t->contains('<a epub:type="figure" href="text/chapter.xhtml#split-figure-one">Figure One</a>', $nav);
            $t->contains('<a epub:type="figure" id="split-figure-two-link" class="split-figure-link" href="text/chapter-2.xhtml#split-figure-two">Figure Two</a>', $nav);
            $t->contains('<nav epub:type="lot" id="split-tables-nav">', $nav);
            $t->contains('<h3>Split Tables</h3>', $nav);
            $t->contains('<a epub:type="table" href="text/chapter-2.xhtml#split-table-two">Table Two</a>', $nav);
        } finally {
            $zip->close();
            @unlink($path);
