        $meta = $roundTrip->attr('meta');
        $diagnosticsJson = json_encode($meta['epubDiagnostics'] ?? [], JSON_THROW_ON_ERROR);
        $t->same(2, $meta['epubAuxiliaryNavSectionCount']);
        $t->same(3, $meta['epubAuxiliaryNavEntryCount']);
        $t->same([
            [
                'type' => 'loi',
                'title' => 'Split Figures',
                'attributes' => [
                    'id' => 'split-figures-nav',
                    'classes' => ['split-figures'],
                    'headingLevel' => 3,
                    'headingAttributes' => [
                        'id' => 'split-figures-heading',
                        'classes' => ['split-aux-heading'],
                    ],
                ],
                'entries' => [
                    [
                        'text' => 'Figure One',
                        'href' => 'OEBPS/text/chapter.xhtml#split-figure-one',
                        'level' => 1,
                        'type' => 'figure',
                    ],
                    [
                        'text' => 'Figure Two',
                        'href' => 'OEBPS/text/chapter-2.xhtml#split-figure-two',
                        'level' => 1,
                        'type' => 'figure',
                        'id' => 'split-figure-two-link',
                        'classes' => ['split-figure-link'],
                    ],
                ],
            ],
            [
                'type' => 'lot',
                'title' => 'Split Tables',
                'attributes' => [
                    'id' => 'split-tables-nav',
                    'headingLevel' => 3,
                ],
                'entries' => [
                    [
                        'text' => 'Table Two',
                        'href' => 'OEBPS/text/chapter-2.xhtml#split-table-two',
                        'level' => 1,
                        'type' => 'table',
                    ],
                ],
            ],
        ], $meta['epubAuxiliaryNavSections']);
        $t->true(!str_contains($diagnosticsJson, 'missing-nav-link-resource'), 'Split auxiliary nav links should target packaged resources.');
        $t->true(!str_contains($diagnosticsJson, 'missing-nav-link-fragment'), 'Split auxiliary nav links should target existing fragments.');
    },
    'writes resource backed non linear epub3 spine itemrefs' => static function (TestRunner $t): void {
