            $t->contains('<item id="book" href="styles/book.css" media-type="text/css"/>', $package);
            $t->contains('<item id="book-remote" href="styles/book-remote.css" media-type="text/css" properties="remote-resources"/>', $package);
            $t->contains('<item id="overlay-remote" href="overlays/overlay-remote.smil" media-type="application/smil+xml" properties="remote-resources"/>', $package);
            $t->contains('<item id="vector-remote" href="images/vector-remote.svg" media-type="image/svg+xml" properties="svg scripted remote-resources"/>', $package);
            $t->contains('<item id="auxiliary" href="text/auxiliary.xhtml" media-type="application/xhtml+xml" properties="mathml svg scripted switch remote-resources"/>', $package);
            $t->contains('<item id="catalog" href="data/catalog.json" media-type="application/json"/>', $package);
            $t->contains('<item id="onix" href="metadata/onix.xml" media-type="application/xml"/>', $package);
            $t->contains('<reference type="cover" title="Cover" href="images/pixel.png"/>', $package);
            $t->contains('<link rel="stylesheet" type="text/css" href="../styles/book.css" />', $chapter);
            $t->contains('<img src="../images/pixel.png" alt="Pixel" />', $chapter);
        } finally {
            $zip->close();
            @unlink($path);
        }

        $roundTrip = PandocConverter::read($epub, 'epub');
        $meta = $roundTrip->attr('meta');
        $diagnosticsJson = json_encode($meta['epubDiagnostics'] ?? [], JSON_THROW_ON_ERROR);
        $t->same(['OEBPS/styles/book.css', 'OEBPS/styles/book-remote.css', 'OEBPS/images/pixel.png'], $meta['epubReferencedResources']);
        $t->same(['OEBPS/images/pixel.png', 'OEBPS/images/vector-remote.svg'], $meta['epubImageResources']);
        $t->same('OEBPS/images/pixel.png', $meta['epubCoverImage']);
        $manifestByPath = [];
        foreach ($meta['epubManifestResources'] ?? [] as $resource) {
            if (is_array($resource) && isset($resource['path'])) {
                $manifestByPath[(string) $resource['path']] = $resource;
            }
        }
        $t->same('application/json', $manifestByPath['OEBPS/data/catalog.json']['mediaType'] ?? null);
        $t->same('application/xml', $manifestByPath['OEBPS/metadata/onix.xml']['mediaType'] ?? null);
        $t->same(['remote-resources'], $manifestByPath['OEBPS/styles/book-remote.css']['properties'] ?? null);
        $t->same(['remote-resources'], $manifestByPath['OEBPS/overlays/overlay-remote.smil']['properties'] ?? null);
        $t->same(['svg', 'scripted', 'remote-resources'], $manifestByPath['OEBPS/images/vector-remote.svg']['properties'] ?? null);
        $t->same(['mathml', 'svg', 'scripted', 'switch', 'remote-resources'], $manifestByPath['OEBPS/text/auxiliary.xhtml']['properties'] ?? null);
        $t->same([
            ['type' => 'cover', 'title' => 'Cover', 'href' => 'OEBPS/images/pixel.png'],
        ], $meta['epubGuideReferences']);
        $t->true(!str_contains($diagnosticsJson, 'invalid-package-opf2-meta'), 'Generated EPUB3 cover metadata should not self-diagnose OPF2 meta name cover.');
        $t->true(!str_contains($diagnosticsJson, 'missing-manifest-required-property'), 'Generated EPUB3 resources should declare required manifest properties.');
    },
    'writes epub3 guide references without invalid target self diagnostics' => static function (TestRunner $t): void {
        $document = new AstNode('document', [
            'meta' => [
                'identifier' => 'urn:uuid:guide-reference-sanitation',
