                    ['type' => 'text', 'title' => 'Start', 'href' => 'OEBPS/text/chapter.xhtml#guide-start'],
                    ['type' => 'loi', 'title' => 'Remote Figures', 'href' => 'https://cdn.example.test/figures.xhtml'],
                    ['type' => 'glossary', 'title' => '', 'href' => 'OEBPS/text/chapter.xhtml#guide-start'],
                    ['type' => 'appendix', 'title' => 'Backmatter', 'href' => 'OEBPS/text/backmatter.xhtml#guide-backmatter'],
                    ['type' => 'appendix', 'title' => 'Backmatter Duplicate', 'href' => 'OEBPS/text/backmatter.xhtml#guide-backmatter'],
                    ['type' => '', 'title' => 'Missing Type', 'href' => 'OEBPS/text/chapter.xhtml#guide-start'],
                    ['type' => 'bad type', 'title' => 'Invalid Type', 'href' => 'OEBPS/text/chapter.xhtml#guide-start'],
                    ['type' => 'text', 'title' => 'Missing Href', 'href' => ''],
                    ['type' => 'loi', 'title' => 'Missing Resource', 'href' => 'OEBPS/missing.xhtml'],
                    ['type' => 'index', 'title' => 'Missing Fragment', 'href' => 'OEBPS/text/chapter.xhtml#missing-fragment'],
                    ['type' => 'text', 'title' => 'Malformed Resource', 'href' => 'OEBPS/text/broken-guide.xhtml#start'],
                    ['type' => 'text', 'title' => 'Image Fragment', 'href' => 'OEBPS/images/diagram.png#diagram'],
                    ['type' => 'text', 'title' => 'Empty Fragment', 'href' => 'OEBPS/text/chapter.xhtml#'],
                    ['type' => 'text', 'title' => 'Whitespace Fragment', 'href' => 'OEBPS/text/chapter.xhtml#bad%20target'],
                    ['type' => 'text', 'title' => 'Query Only', 'href' => '?print=1'],
                    ['type' => 'cover', 'title' => 'Fragment Only', 'href' => '#cover'],
                    ['type' => 'cover', 'title' => 'Data Cover', 'href' => 'data:image/svg+xml;base64,PHN2Zy8+'],
                    ['type' => 'text', 'title' => 'File Guide', 'href' => 'file:///tmp/chapter.xhtml'],
                    ['type' => 'text', 'title' => 'Absolute Path', 'href' => '/chapter.xhtml'],
                    ['type' => 'text', 'title' => 'Protocol Relative', 'href' => '//cdn.example.test/chapter.xhtml'],
                    ['type' => 'text', 'title' => 'Backslash Path', 'href' => 'chapters\\one.xhtml'],
                    ['type' => 'text', 'title' => 'Encoded Dot Segment', 'href' => 'chapters/%2e%2e/chapter.xhtml'],
                ],
            ],
        ], [
            new AstNode('heading', ['level' => 1, 'text' => 'Guide Reference Sanitation', 'id' => 'guide-start'], [
                new AstNode('text', ['text' => 'Guide Reference Sanitation']),
            ]),
            new AstNode('paragraph', [], [
                new AstNode('text', ['text' => 'Guide reference sanitation body.']),
            ]),
        ]);

        $epub = PandocConverter::write($document, 'epub3', [
            'modified' => '2026-06-23T08:00:00Z',
            'resources' => [
                'OEBPS/text/backmatter.xhtml' => '<html xmlns="http://www.w3.org/1999/xhtml"><body><section id="guide-backmatter"><h1>Backmatter</h1></section></body></html>',
                'OEBPS/text/broken-guide.xhtml' => '<html xmlns="http://www.w3.org/1999/xhtml"><body><p id="start">Broken guide target</p>',
                'OEBPS/images/diagram.png' => 'not-a-real-png',
            ],
        ]);
        $path = tempnam(sys_get_temp_dir(), 'pandoc-epub-guide-reference-sanitized-');
        if ($path === false) {
            throw new RuntimeException('Unable to create temporary generated EPUB path');
        }
        file_put_contents($path, $epub);

        $zip = new ZipArchive();
        try {
            if ($zip->open($path) !== true) {
                throw new RuntimeException('Unable to open generated EPUB package');
            }
            $package = $zip->getFromName('OEBPS/package.opf');
            if (!is_string($package)) {
                throw new RuntimeException('Generated EPUB package is missing package OPF');
            }

            $t->contains('<reference type="text" title="Start" href="text/chapter.xhtml#guide-start"/>', $package);
            $t->contains('<reference type="loi" title="Remote Figures" href="https://cdn.example.test/figures.xhtml"/>', $package);
            $t->contains('<reference type="glossary" title="Glossary" href="text/chapter.xhtml#guide-start"/>', $package);
            $t->contains('<reference type="appendix" title="Backmatter" href="text/backmatter.xhtml#guide-backmatter"/>', $package);
            foreach ([
                'Backmatter Duplicate',
                'Missing Type',
                'Invalid Type',
                'Missing Href',
                'Missing Resource',
                'Missing Fragment',
                'Malformed Resource',
                'Image Fragment',
                'Empty Fragment',
                'Whitespace Fragment',
                'Query Only',
                'Fragment Only',
                'Data Cover',
                'File Guide',
                'Absolute Path',
                'Protocol Relative',
                'Backslash Path',
                'Encoded Dot Segment',
            ] as $omittedGuideReference) {
                $t->true(!str_contains($package, $omittedGuideReference), "Invalid guide reference should not be emitted: {$omittedGuideReference}.");
            }
        } finally {
            $zip->close();
            @unlink($path);
        }

        $roundTrip = PandocConverter::read($epub, 'epub');
        $meta = $roundTrip->attr('meta');
        $diagnosticsJson = json_encode($meta['epubDiagnostics'] ?? [], JSON_THROW_ON_ERROR);
        $guideReferencesJson = json_encode($meta['epubGuideReferences'] ?? [], JSON_THROW_ON_ERROR);
        $t->same([
            ['type' => 'text', 'title' => 'Start', 'href' => 'OEBPS/text/chapter.xhtml#guide-start'],
            ['type' => 'loi', 'title' => 'Remote Figures', 'href' => 'https://cdn.example.test/figures.xhtml'],
            ['type' => 'glossary', 'title' => 'Glossary', 'href' => 'OEBPS/text/chapter.xhtml#guide-start'],
            ['type' => 'appendix', 'title' => 'Backmatter', 'href' => 'OEBPS/text/backmatter.xhtml#guide-backmatter'],
        ], $meta['epubGuideReferences'] ?? null);
        foreach ([
            'missing-guide-reference-type',
            'invalid-guide-reference-type',
            'missing-guide-reference-title',
            'missing-guide-reference-href',
            'missing-guide-reference-resource',
            'missing-guide-reference-manifest-resource',
            'missing-guide-reference-fragment',
            'malformed-guide-reference-resource',
            'invalid-guide-reference-href-path',
            'invalid-guide-reference-href-fragment',
            'invalid-guide-reference-data-url',
            'invalid-guide-reference-file-url',
        ] as $diagnosticCode) {
            $t->true(!str_contains($diagnosticsJson, $diagnosticCode), "Generated guide references should not self-diagnose {$diagnosticCode}.");
        }
        foreach (['Backmatter Duplicate', 'Missing Resource', 'Missing Fragment', 'Malformed Resource', 'Image Fragment', 'Data Cover', 'File Guide'] as $omitted) {
            $t->true(!str_contains($guideReferencesJson, $omitted), "Invalid guide reference should not round-trip: {$omitted}.");
        }
    },
