            }
            $package = $zip->getFromName('OEBPS/package.opf');
            if (!is_string($package)) {
                throw new RuntimeException('Generated EPUB package is missing package file');
            }

            $t->contains('<link href="metadata/record.xml" rel="record" media-type="application/xml" id="existing-package-record"/>', $package);
            $t->contains('<link href="https://metadata.example.test/record.xml" rel="record" media-type="application/xml" id="remote-package-record"/>', $package);
            $t->contains('<link href="metadata/series.xml" rel="record" media-type="application/xml" id="existing-collection-record"/>', $package);
            $t->contains('<link href="text/chapter.xhtml" rel="contents" id="existing-collection-member"/>', $package);
            $t->contains('<link href="metadata/member.json" rel="contents" media-type="application/json" id="collection-sidecar-member"/>', $package);
            $t->contains('<link href="https://metadata.example.test/series" rel="contents" id="remote-collection-member"/>', $package);
            $t->contains('<link href="metadata/series.xml" rel="record" media-type="application/xml" id="existing-nested-collection-record"/>', $package);
            $t->contains('<link href="text/chapter.xhtml" rel="contents" id="existing-nested-collection-member"/>', $package);
            $t->contains('<link href="metadata/nested-member.json" rel="contents" media-type="application/json" id="nested-collection-sidecar-member"/>', $package);
            $t->true(!str_contains($package, '<item id="member-payload"'), 'Collection sidecar link resources should not be duplicated into the manifest.');
            $t->true(!str_contains($package, '<item id="nested-member-payload"'), 'Nested collection sidecar link resources should not be duplicated into the manifest.');
