            $t->true(!str_contains($package, 'missing-collection-record'), 'Missing local collection metadata links should not be emitted.');
            $t->true(!str_contains($package, 'missing-collection-member'), 'Missing local direct collection links should not be emitted.');
            $t->true(!str_contains($package, 'malformed-collection-record'), 'Malformed collection metadata link fragment targets should not be emitted.');
            $t->true(!str_contains($package, 'malformed-collection-member'), 'Malformed direct collection link fragment targets should not be emitted.');
            $t->true(!str_contains($package, 'malformed-nested-collection-record'), 'Malformed nested collection metadata link fragment targets should not be emitted.');
            $t->true(!str_contains($package, 'malformed-nested-collection-member'), 'Malformed nested collection member link fragment targets should not be emitted.');
