        $diagnosticsJson = json_encode($meta['epubDiagnostics'] ?? [], JSON_THROW_ON_ERROR);
        $metadataLinksJson = json_encode($meta['epubMetadataLinks'] ?? [], JSON_THROW_ON_ERROR);
        $collectionsJson = json_encode($meta['epubCollections'] ?? [], JSON_THROW_ON_ERROR);
