        $t->contains('existing-collection-record', $collectionsJson);
        $t->contains('existing-collection-member', $collectionsJson);
        $t->contains('collection-sidecar-member', $collectionsJson);
        $t->contains('remote-collection-member', $collectionsJson);
        $t->contains('existing-nested-collection-record', $collectionsJson);
        $t->contains('existing-nested-collection-member', $collectionsJson);
        $t->contains('nested-collection-sidecar-member', $collectionsJson);
        $packageLinkResourcesByPath = [];
        foreach ($meta['epubPackageLinkResources'] ?? [] as $resource) {
            if (is_array($resource) && isset($resource['path'])) {
