            }
        }
        $t->same('collection-sidecar-member', $packageLinkResourcesByPath['OEBPS/metadata/member.json']['id'] ?? null);
        $t->same('contents', $packageLinkResourcesByPath['OEBPS/metadata/member.json']['rel'] ?? null);
        $t->same('collection', $packageLinkResourcesByPath['OEBPS/metadata/member.json']['parent'] ?? null);
        $t->same('series', $packageLinkResourcesByPath['OEBPS/metadata/member.json']['collectionId'] ?? null);
        $t->same('nested-collection-sidecar-member', $packageLinkResourcesByPath['OEBPS/metadata/nested-member.json']['id'] ?? null);
