        $t->same($recordXml, base64_decode($meta['epubResourcePayloads']['OEBPS/metadata/record.xml']['data'] ?? '', true));
        $t->same($seriesXml, base64_decode($meta['epubResourcePayloads']['OEBPS/metadata/series.xml']['data'] ?? '', true));
        $t->same($memberJson, base64_decode($meta['epubResourcePayloads']['OEBPS/metadata/member.json']['data'] ?? '', true));
        $t->same($nestedMemberJson, base64_decode($meta['epubResourcePayloads']['OEBPS/metadata/nested-member.json']['data'] ?? '', true));
