        $t->same('en-GB', $meta['epubMetadataLinks'][0]['hreflang'] ?? null);
        $t->same('en', $meta['epubMetadataLinks'][0]['lang'] ?? null);
        $t->same('ltr', $meta['epubMetadataLinks'][0]['dir'] ?? null);
        $t->same('catalog-record', $meta['epubMetadataLinks'][1]['id'] ?? null);
        $t->same('OEBPS/metadata/catalog.json', $meta['epubMetadataLinks'][1]['href'] ?? null);
        $t->same('alternate', $meta['epubMetadataLinks'][1]['rel'] ?? null);
        $t->same('#book-id', $meta['epubMetadataLinks'][1]['refines'] ?? null);
        $t->same('pl', $meta['epubMetadataLinks'][1]['hreflang'] ?? null);
        $t->same('pl', $meta['epubMetadataLinks'][1]['lang'] ?? null);
        $t->same('rtl', $meta['epubMetadataLinks'][1]['dir'] ?? null);
        $t->same(['preview'], $meta['epubMetadataLinks'][1]['properties'] ?? null);
        $t->same('application/json', $meta['epubMetadataLinks'][1]['mediaType'] ?? null);
        $t->same([
            'id' => 'onix-record',
            'href' => 'metadata/onix.xml',
            'path' => 'OEBPS/metadata/onix.xml',
            'mediaType' => 'application/xml',
            'properties' => ['onix'],
            'rel' => 'record',
            'hreflang' => 'en-GB',
            'lang' => 'en',
            'dir' => 'ltr',
            'parent' => 'metadata',
        ], $packageLinkResourcesByPath['OEBPS/metadata/onix.xml'] ?? null);
        $t->same([
            'id' => 'catalog-record',
            'href' => 'metadata/catalog.json',
            'path' => 'OEBPS/metadata/catalog.json',
            'mediaType' => 'application/json',
            'properties' => ['preview'],
            'rel' => 'alternate',
            'refines' => '#book-id',
            'hreflang' => 'pl',
            'lang' => 'pl',
            'dir' => 'rtl',
            'parent' => 'metadata',
        ], $packageLinkResourcesByPath['OEBPS/metadata/catalog.json'] ?? null);
