        $t->same($catalog, base64_decode($resourceMeta['epubResourcePayloads']['OEBPS/metadata/catalog.json']['data'] ?? '', true));
        $diagnosticsJson = json_encode($meta['epubDiagnostics'] ?? [], JSON_THROW_ON_ERROR);
        $t->true(!str_contains($diagnosticsJson, 'invalid-package-link-manifest-resource'), 'Generated metadata-link payloads should not self-diagnose as manifest resources.');
        $t->true(!str_contains($diagnosticsJson, 'missing-package-link-media-type'), 'Generated metadata-link payloads should infer media types instead of self-diagnosing missing media-type.');
        $t->true(!str_contains($diagnosticsJson, 'invalid-package-link-record-refines'), 'Generated package metadata record links should not self-diagnose invalid refines attributes.');
        $identifierType = null;
        $titleType = null;
        $displaySeq = null;
        $accessibilitySummary = null;
        foreach ($meta['epubMetadataProperties'] as $property) {
            if (!is_array($property)) {
                continue;
            }
            if (($property['property'] ?? null) === 'identifier-type') {
                $identifierType = $property;
            }
            if (($property['property'] ?? null) === 'title-type') {
                $titleType = $property;
            }
            if (($property['property'] ?? null) === 'display-seq') {
                $displaySeq = $property;
            }
            if (($property['property'] ?? null) === 'schema:accessibilitySummary') {
                $accessibilitySummary = $property;
            }
        }
        $t->same('#book-id', $identifierType['refines'] ?? null);
        $t->same('onix:codelist5', $identifierType['scheme'] ?? null);
        $t->same('#title-main', $titleType['refines'] ?? null);
        $t->same('#creator-primary', $displaySeq['refines'] ?? null);
        $t->same('en', $accessibilitySummary['lang'] ?? null);
        $t->same('ltr', $accessibilitySummary['dir'] ?? null);
        $creator = null;
        foreach ($meta['epubDublinCoreMetadata'] as $record) {
            if (is_array($record) && ($record['element'] ?? null) === 'creator') {
                $creator = $record;
                break;
            }
        }
        $t->same('Ada Lovelace', $creator['value'] ?? null);
        $t->same('creator-primary', $creator['id'] ?? null);
        $t->same('Lovelace, Ada', $creator['fileAs'] ?? null);
        $t->same('aut', $creator['role'] ?? null);
    },
