                throw new RuntimeException('Unable to open generated EPUB package');
            }
            $package = $zip->getFromName('OEBPS/package.opf');
            $chapter = $zip->getFromName('OEBPS/text/chapter.xhtml');
            if (!is_string($package) || !is_string($chapter)) {
                throw new RuntimeException('Generated EPUB package is missing package or chapter file');
            }

            $t->same($onix, $zip->getFromName('OEBPS/metadata/onix.xml'));
            $t->same($broken, $zip->getFromName('OEBPS/metadata/broken.xml'));
            $t->same($diagram, $zip->getFromName('OEBPS/images/diagram.png'));
            $t->contains('<h1 id="chapter-start">Metadata Resource Refines</h1>', $chapter);
            $t->contains('<meta property="source-of" id="onix-source" refines="metadata/onix.xml#record">metadata sidecar</meta>', $package);
            $t->contains('<meta property="source-of" id="chapter-source" refines="text/chapter.xhtml#chapter-start">chapter section</meta>', $package);
            $t->contains('<meta property="title-type" id="package-path-title" refines="package.opf#title-main">main</meta>', $package);
            $t->contains('<meta property="source-of" id="missing-resource">missing resource</meta>', $package);
            $t->contains('<meta property="source-of" id="missing-onix-fragment">missing onix fragment</meta>', $package);
            $t->contains('<meta property="source-of" id="missing-chapter-fragment">missing chapter fragment</meta>', $package);
            $t->contains('<meta property="source-of" id="broken-resource">broken resource</meta>', $package);
            $t->contains('<meta property="source-of" id="image-fragment">image fragment</meta>', $package);
            $t->contains('<meta property="source-of" id="absolute-refines">absolute refines</meta>', $package);
            $t->contains('<link href="metadata/onix.xml" rel="alternate" media-type="application/xml" refines="metadata/onix.xml#record" id="onix-alternate"/>', $package);
            $t->contains('<link href="metadata/onix.xml" rel="alternate" media-type="application/xml" id="missing-link-fragment"/>', $package);
            $t->contains('<link href="metadata/onix.xml" rel="alternate" media-type="application/xml" id="broken-link-fragment"/>', $package);
            $t->contains('<link href="metadata/onix.xml" rel="alternate" media-type="application/xml" id="image-link-fragment"/>', $package);
            $t->contains('<link href="metadata/onix.xml" rel="record" media-type="application/xml" id="record-link"/>', $package);
            foreach ([
                'refines="metadata/missing.xml#record"',
                'refines="metadata/onix.xml#missing-record"',
                'refines="text/chapter.xhtml#missing-heading"',
                'refines="metadata/broken.xml#record"',
                'refines="images/diagram.png#diagram"',
                'refines="https://metadata.example.test/onix.xml#record"',
            ] as $missingRefines) {
                $t->true(!str_contains($package, $missingRefines), "Invalid resource metadata refines should not be emitted: {$missingRefines}.");
            }
        } finally {
            $zip->close();
            @unlink($path);
        }

        $roundTrip = PandocConverter::read($epub, 'epub');
        $meta = $roundTrip->attr('meta');
        $diagnosticsJson = json_encode($meta['epubDiagnostics'] ?? [], JSON_THROW_ON_ERROR);
        foreach ([
            'invalid-metadata-refines',
            'missing-metadata-refines-resource',
            'missing-metadata-refines-fragment',
            'missing-metadata-refines-target',
            'malformed-metadata-refines-resource',
            'invalid-package-link-record-refines',
