            $t->true(!str_contains($diagnosticsJson, $code), "Generated resource metadata refines should not self-diagnose {$code}.");
        }

        $propertiesById = [];
        foreach ($meta['epubMetadataProperties'] ?? [] as $property) {
            if (is_array($property) && isset($property['id'])) {
                $propertiesById[$property['id']] = $property;
            }
        }
        $linksById = [];
        foreach ($meta['epubMetadataLinks'] ?? [] as $link) {
            if (is_array($link) && isset($link['id'])) {
                $linksById[$link['id']] = $link;
            }
        }

        $t->same('metadata/onix.xml#record', $propertiesById['onix-source']['refines'] ?? null);
        $t->same('text/chapter.xhtml#chapter-start', $propertiesById['chapter-source']['refines'] ?? null);
        $t->same('package.opf#title-main', $propertiesById['package-path-title']['refines'] ?? null);
        foreach (['missing-resource', 'missing-onix-fragment', 'missing-chapter-fragment', 'broken-resource', 'image-fragment', 'absolute-refines'] as $id) {
            $t->true(!array_key_exists('refines', $propertiesById[$id] ?? []), "Invalid resource metadata refines should not round-trip for {$id}.");
        }
        $t->same('metadata/onix.xml#record', $linksById['onix-alternate']['refines'] ?? null);
        $t->true(!array_key_exists('refines', $linksById['missing-link-fragment'] ?? []), 'Invalid metadata-link resource refines should not round-trip.');
        $t->true(!array_key_exists('refines', $linksById['broken-link-fragment'] ?? []), 'Malformed metadata-link resource refines should not round-trip.');
        $t->true(!array_key_exists('refines', $linksById['image-link-fragment'] ?? []), 'Non-XML metadata-link resource refines should not round-trip.');
        $t->true(!array_key_exists('refines', $linksById['record-link'] ?? []), 'Record metadata links should still not round-trip refines.');
    },
