            ]),
            new AstNode('paragraph', [], [
                new AstNode('text', ['text' => 'First split resource refines body.']),
            ]),
            new AstNode('heading', ['level' => 1, 'text' => 'Split Refines Two', 'id' => 'split-refines-two'], [
                new AstNode('text', ['text' => 'Split Refines Two']),
            ]),
            new AstNode('paragraph', [], [
                new AstNode('text', ['text' => 'Second split resource refines body.']),
            ]),
        ]);

        $epub = PandocConverter::write($document, 'epub3', [
            'modified' => '2026-06-23T17:20:00Z',
            'splitLevel' => 1,
        ]);
        $path = tempnam(sys_get_temp_dir(), 'pandoc-epub-split-resource-refines-');
        if ($path === false) {
            throw new RuntimeException('Unable to create temporary split refines EPUB path');
        }
        file_put_contents($path, $epub);

        $zip = new ZipArchive();
        try {
            if ($zip->open($path) !== true) {
                throw new RuntimeException('Unable to open generated split refines EPUB package');
            }
            $package = $zip->getFromName('OEBPS/package.opf');
            $chapterOne = $zip->getFromName('OEBPS/text/chapter.xhtml');
            $chapterTwo = $zip->getFromName('OEBPS/text/chapter-2.xhtml');
            if (!is_string($package) || !is_string($chapterOne) || !is_string($chapterTwo)) {
                throw new RuntimeException('Generated split refines EPUB is missing package or split chapter files');
            }

            $t->same($record, $zip->getFromName('OEBPS/metadata/split-refines.json'));
            $t->contains('<h1 id="split-refines-one">Split Refines One</h1>', $chapterOne);
            $t->true(!str_contains($chapterOne, 'split-refines-two'), 'Second split refines heading should move out of the first chapter.');
            $t->contains('<h1 id="split-refines-two">Split Refines Two</h1>', $chapterTwo);
            $t->contains('<meta property="source-of" id="split-first-source" refines="text/chapter.xhtml#split-refines-one">first split chapter</meta>', $package);
            $t->contains('<meta property="source-of" id="split-second-source" refines="text/chapter-2.xhtml#split-refines-two">second split chapter</meta>', $package);
            $t->contains('<meta property="source-of" id="split-missing-source">missing split chapter</meta>', $package);
            $t->contains('<link href="metadata/split-refines.json" rel="alternate" media-type="application/json" refines="text/chapter.xhtml#split-refines-one" id="split-first-link"/>', $package);
            $t->contains('<link href="metadata/split-refines.json" rel="alternate" media-type="application/json" refines="text/chapter-2.xhtml#split-refines-two" id="split-second-link"/>', $package);
            $t->contains('<link href="metadata/split-refines.json" rel="alternate" media-type="application/json" id="split-missing-link"/>', $package);
            $t->true(!str_contains($package, 'refines="text/chapter-2.xhtml#missing-split-refines"'), 'Missing split chapter fragments should not be emitted as metadata refines.');
        } finally {
            $zip->close();
            @unlink($path);
        }

        $roundTrip = PandocConverter::read($epub, 'epub');
        $meta = $roundTrip->attr('meta');
        $diagnosticsJson = json_encode($meta['epubDiagnostics'] ?? [], JSON_THROW_ON_ERROR);
        foreach ([
            'invalid-metadata-refines',
            'missing-metadata-refines-resource',
            'missing-metadata-refines-fragment',
            'missing-metadata-refines-target',
            'invalid-package-link-record-refines',
        ] as $code) {
            $t->true(!str_contains($diagnosticsJson, $code), "Generated split resource metadata refines should not self-diagnose {$code}.");
        }

        $propertiesById = [];
        foreach ($meta['epubMetadataProperties'] ?? [] as $property) {
            if (is_array($property) && isset($property['id'])) {
                $propertiesById[$property['id']] = $property;
            }
        }
        $linksById = [];
        foreach ($meta['epubMetadataLinks'] ?? [] as $link) {
            if (is_array($link) && isset($link['id'])) {
                $linksById[$link['id']] = $link;
            }
        }

        $t->same('text/chapter.xhtml#split-refines-one', $propertiesById['split-first-source']['refines'] ?? null);
        $t->same('text/chapter-2.xhtml#split-refines-two', $propertiesById['split-second-source']['refines'] ?? null);
        $t->true(!array_key_exists('refines', $propertiesById['split-missing-source'] ?? []), 'Missing split metadata property refines should not round-trip.');
        $t->same('text/chapter.xhtml#split-refines-one', $linksById['split-first-link']['refines'] ?? null);
        $t->same('text/chapter-2.xhtml#split-refines-two', $linksById['split-second-link']['refines'] ?? null);
        $t->true(!array_key_exists('refines', $linksById['split-missing-link'] ?? []), 'Missing split metadata-link refines should not round-trip.');
    },
