            $t->true(!str_contains($primaryPackage, 'metadata/alternate.xml'), 'Alternate resourcePayloads entry leaked into the primary OPF.');
            $t->true(!str_contains($alternatePackage, 'styles/primary.css'), 'Primary direct resources leaked into the alternate OPF.');
