            $t->same($mobileJson, $zip->getFromName('META-INF/metadata/mobile.json'));
            $t->same($printCss, $zip->getFromName('ALT/print/styles/print.css'));
            $t->same($mobileCss, $zip->getFromName('MOBI/styles/mobile.css'));
            $t->true(!str_contains($primaryPackage, 'ALT/print.opf'), 'Print alternate OPF was incorrectly written into the primary OPF manifest.');
            $t->true(!str_contains($primaryPackage, 'MOBI/mobile.opf'), 'Mobile alternate OPF was incorrectly written into the primary OPF manifest.');
            $t->true(!str_contains($primaryPackage, 'metadata/print.json'), 'Print OCF graph sidecar was incorrectly written into the primary OPF manifest.');
