        $t->same('mobile-rendition', $meta['epubContainerRootfiles'][2]['id'] ?? null);
        $t->same('META-INF/metadata/print.json', $meta['epubContainerLinks'][0]['href'] ?? null);
        $t->same('#print-rendition', $meta['epubContainerLinks'][0]['refines'] ?? null);
        $t->same('META-INF/metadata/mobile.json', $meta['epubContainerLinks'][1]['href'] ?? null);
        $t->same('#mobile-rendition', $meta['epubContainerLinks'][1]['refines'] ?? null);
        $t->same($printJson, base64_decode($meta['epubOcfSidecarPayloads']['META-INF/metadata/print.json']['data'] ?? '', true));
        $t->same($mobileJson, base64_decode($meta['epubOcfSidecarPayloads']['META-INF/metadata/mobile.json']['data'] ?? '', true));
        $t->same('Print Graph Rendition', $print['title'] ?? null);
