            $t->same($pageOneAudio, $zip->getFromName('ALT/audio/page-one.mp3'));
            $t->same($pageTwoAudio, $zip->getFromName('ALT/audio/page-two.mp3'));
            $t->true(!str_contains($primaryPackage, 'mo-fixed-page-one'), 'Alternate fixed media overlay leaked into the primary OPF.');
            $t->true(!str_contains($primaryPackage, 'page-one.mp3'), 'Alternate fixed audio resource leaked into the primary OPF.');
        } finally {
            $zip->close();
            @unlink($path);
        }

        $roundTrip = PandocConverter::read($epub, 'epub', ['extractResources' => true]);
        $meta = $roundTrip->attr('meta');
        $alternate = $meta['epubAlternateRootfilePackages']['ALT/fixed-overlay.opf'] ?? [];
        $overlays = $alternate['epubMediaOverlays'] ?? [];
        $diagnosticsJson = json_encode($alternate['epubDiagnostics'] ?? [], JSON_THROW_ON_ERROR);

        $t->same('rtl', $alternate['epubPageProgressionDirection'] ?? null);
        $t->same('pre-paginated', $alternate['epubRenditionLayout'] ?? null);
        $t->same('landscape', $alternate['epubRenditionOrientation'] ?? null);
        $t->same('paginated', $alternate['epubRenditionFlow'] ?? null);
        $t->same(2, $alternate['epubMediaOverlayCount'] ?? null);
        $t->same(['ALT/overlays/mo-fixed-page-one.smil', 'ALT/overlays/mo-fixed-page-two.smil'], $alternate['epubMediaOverlayResources'] ?? null);
        $t->same('mo-fixed-page-one', $alternate['epubSpineItemRefs'][0]['mediaOverlay'] ?? null);
        $t->same('mo-fixed-page-two', $alternate['epubSpineItemRefs'][1]['mediaOverlay'] ?? null);
        $t->same('fixed-page-one-ref', $alternate['epubSpineItemRefs'][0]['id'] ?? null);
        $t->same('fixed-page-two-ref', $alternate['epubSpineItemRefs'][1]['id'] ?? null);
        $t->same('right', $alternate['epubSpineItemRefs'][0]['pageSpread'] ?? null);
        $t->same('left', $alternate['epubSpineItemRefs'][1]['pageSpread'] ?? null);
        $t->same('landscape', $alternate['epubSpineItemRefs'][0]['renditionOrientation'] ?? null);
        $t->same('portrait', $alternate['epubSpineItemRefs'][1]['renditionOrientation'] ?? null);
        $t->same(['width' => 1200, 'height' => 900, 'content' => 'width=1200, height=900'], $alternate['epubSpineItemRefs'][0]['viewport'] ?? null);
        $t->same(['width' => 900, 'height' => 1200, 'content' => 'width=900, height=1200'], $alternate['epubSpineItemRefs'][1]['viewport'] ?? null);
        $t->same('mo-fixed-page-one', $overlays[0]['overlayId'] ?? null);
        $t->same('ALT/text/narrated.xhtml', $overlays[0]['contentPath'] ?? null);
        $t->same(['ALT/text/narrated.xhtml#narrated-fixed-page-one'], $overlays[0]['textTargets'] ?? null);
        $t->same(['ALT/audio/page-one.mp3'], $overlays[0]['audioTargets'] ?? null);
        $t->same('mo-fixed-page-two', $overlays[1]['overlayId'] ?? null);
        $t->same('ALT/text/narrated-2.xhtml', $overlays[1]['contentPath'] ?? null);
        $t->same(['ALT/text/narrated-2.xhtml#narrated-fixed-page-two'], $overlays[1]['textTargets'] ?? null);
        $t->same(['ALT/audio/page-two.mp3'], $overlays[1]['audioTargets'] ?? null);
        $t->same($pageOneAudio, base64_decode($alternate['epubResourcePayloads']['ALT/audio/page-one.mp3']['data'] ?? '', true));
        $t->same($pageTwoAudio, base64_decode($alternate['epubResourcePayloads']['ALT/audio/page-two.mp3']['data'] ?? '', true));
        $t->same('Narrated Fixed Page One First narrated fixed page. Narrated Fixed Page Two Second narrated fixed page.', $alternate['epubBodyText'] ?? null);
        $t->true(!str_contains($diagnosticsJson, 'missing-media-overlay-resource'), 'Generated fixed overlay resources should not self-diagnose missing overlay resources.');
        $t->true(!str_contains($diagnosticsJson, 'missing-media-overlay-text'), 'Generated fixed overlay SMIL should not self-diagnose missing text targets.');
        $t->true(!str_contains($diagnosticsJson, 'missing-media-overlay-audio'), 'Generated fixed overlay SMIL should not self-diagnose missing audio targets.');
    },
];
